import requests
from pathlib import Path
import zipfile

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    """
    Downloads a ZIP file from the specified URL and extracts it.

    Args:
        url (str): The URL to download the ZIP file from.
        filename (str): The name to save the downloaded ZIP file as.

    Returns:
        tuple: (status_message, [list_of_extracted_filenames])
               On error, status_message contains "Error" and the list is [].
    """
    # Ensure directories exist
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return (f"Error: Failed to create directories: {e}", [])

    zip_path = DOWNLOAD_DIR / filename

    # Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with zip_path.open("wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        return (f"Error: Failed to download file from {url}: {e}", [])
    except OSError as e:
        return (f"Error: Failed to write downloaded file: {e}", [])

    # Extract the ZIP file
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            for member in zip_ref.infolist():
                # Only list regular files, not directories
                if not member.is_dir():
                    extracted_files.append(str(ZIP_DIR / member.filename))
    except (zipfile.BadZipFile, zipfile.LargeZipFile) as e:
        return (f"Error: ZIP file is invalid or corrupted: {e}", [])
    except OSError as e:
        return (f"Error: Failed during file extraction: {e}", [])

    return ("Download and extraction successful", extracted_files)
